 branding:[['school_name','School Name'],['motto','Institutional Values'],['affiliation','CBSE Affiliation Number'],['logo_url','Logo URL / Upload','media'],['intro','Short Introduction','area'],['address','School Address','area'],['phone','Primary Office Phone'],['secondary_phone','Alternate Office Phone'],['security_phone','Security Helpdesk Phone'],['contact_description','Contact Page Description','area'],['email','Verified Office Email'],['office_hours','Office Hours'],['social','Official Social Accounts (JSON)','json']],
