 homepage:[['about_heading','About Heading'],['about_text','About Text','area'],['about_image','About Image URL','media'],['vision','Our Vision','area'],['mission','Our Mission','area'],['values','Our Values','area'],['cta_heading','Admission CTA Heading'],['cta_text','Admission CTA Text','area']],
